-- 运行前加密备份、隔离恢复验证；MySQL客户端必须遇首错停止。
USE token;
SET NAMES utf8mb4;
SET time_zone = '+00:00';
SET @token_polish_sql_mode=@@SESSION.sql_mode;
SET SESSION sql_mode=CONCAT_WS(',',@@SESSION.sql_mode,'STRICT_ALL_TABLES');
CREATE TEMPORARY TABLE token_polish_guard (verified TINYINT NOT NULL);
INSERT INTO token_polish_guard SELECT IF(BINARY DATABASE()=BINARY 'token' AND (SELECT COUNT(*) FROM system_setting WHERE setting_key='i18n.translations.revision')=1,1,NULL);
START TRANSACTION;
SELECT setting_key FROM system_setting WHERE setting_key='i18n.translations.revision' FOR UPDATE;
SET @token_polish_inserted=0, @token_polish_filled=0;
INSERT INTO translates(tkey,lang,tvalue,type,prop,title,is_del,action_time) SELECT CONVERT(0x757365722e706f6c6973682e7265636f7264732e6e6f7453756363657373 USING utf8mb4),CONVERT(0x7a68 USING utf8mb4),CONVERT(0xe4b88de68890e58a9f USING utf8mb4),7,0,CONVERT(0x414920566f726120e7958ce99da2e5ae8ce59684 USING utf8mb4),0,UTC_TIMESTAMP(6) WHERE NOT EXISTS(SELECT 1 FROM translates WHERE type=7 AND BINARY tkey=BINARY CONVERT(0x757365722e706f6c6973682e7265636f7264732e6e6f7453756363657373 USING utf8mb4) AND BINARY lang=BINARY CONVERT(0x7a68 USING utf8mb4));
SET @token_polish_inserted=@token_polish_inserted+ROW_COUNT();
